describe("doctests of sympy.sets.conditionset", () => {
  it("2*pi in sin_sols", () => {
    const x = new Sym('x');
    expect(sympyStr(new ConditionSet(x, Relational(fn('sin', [x], { evaluate: false }), Rational.of(0n, 1n, { gcd: 1n }), '==', { evaluate: false }), interval(Rational.of(0n, 1n, { gcd: 1n }), mul(Rational.of(2n, 1n, { gcd: 1n }), pi), false, false)).hasElement(mul(Rational.of(2n, 1n, { gcd: 1n }), pi)))).toBe('True');
  });
  it("pi/2 in sin_sols", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("3*pi in sin_sols", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("5 in ConditionSet(x, x**2 > 4, S.Reals)", () => {
    const x = new Sym('x');
    expect(sympyStr(new ConditionSet(x, Relational(pow(x, Rational.of(2n, 1n, { gcd: 1n })), Rational.of(4n, 1n, { gcd: 1n }), '>', { evaluate: false }), Reals).hasElement(Rational.of(5n, 1n, { gcd: 1n })))).toBe('True');
  });
  it("5 in ConditionSet(x, x**2 > 4, Interval(2, 4))", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("ConditionSet(n, cond, S.Integers)", () => {
    const n = new Sym('n', { negative: true });
    expect(sympyStr(ConditionSet.of(n, S['false'], Integers))).toBe('EmptySet');
  });
  it("c.subs(x, y)", () => {
    const [x, z, y] = symbols('x z y');
    expect(sympyStr(new ConditionSet(x, Relational(x, Rational.of(1n, 1n, { gcd: 1n }), '<', { evaluate: false }), finiteSet(x, z)).subs(x, y))).toBe('ConditionSet(x, x < 1, {y, z})');
  });
  it("pi in c", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("ConditionSet(x, x < 1).base_set", () => {
    expect(sympyStr(UniversalSet)).toBe('UniversalSet');
  });
  it("ConditionSet(x, x < y, ConditionSet(z, z + y < 2, S.Integers))", () => {
    const [x, y, z] = symbols('x y z');
    expect(sympyStr(ConditionSet.of(x, Relational(x, y, '<', { evaluate: false }), new ConditionSet(z, Relational(add(y, z), Rational.of(2n, 1n, { gcd: 1n }), '<', { evaluate: false }), Integers)))).toBe('ConditionSet(x, (x < y) & (x + y < 2), Integers)');
  });
});

